pub struct ModelObject;

impl ObjectTrait for ModelObject {
    fn name(&self) -> (&str, &str) {
        MODEL_NAMES
    }

    fn type_name(&self) -> &str {
        MODEL_TYPE_NAME
    }

    fn type_mapping(&self) -> &TypeMapping {
        &MODEL_TYPE_MAPPING
    }

    fn input_objects(&self) -> Option<Vec<InputObject>> {
        let order = InputObject::new(MODEL_ORDER_TYPE_NAME)
            .field(InputValue::new("direction", TypeRef::named_nn(ORDER_DIR_TYPE_NAME)))
            .field(InputValue::new("field", TypeRef::named_nn(MODEL_ORDER_FIELD_TYPE_NAME)));

        Some(vec![order])
    }

    fn enum_objects(&self) -> Option<Vec<Enum>> {
        let direction = Enum::new(ORDER_DIR_TYPE_NAME).item(ORDER_ASC).item(ORDER_DESC);
        let field_order = Enum::new(MODEL_ORDER_FIELD_TYPE_NAME).item("NAME").item("CLASS_HASH");

        Some(vec![direction, field_order])
    }

    fn resolve_many(&self) -> Option<Field> {
        let mut field = Field::new(
            self.name().1,
            TypeRef::named(format!("{}Connection", self.type_name())),
            |ctx| {
                FieldFuture::new(async move {
                    let mut conn = ctx.data::<Pool<Sqlite>>()?.acquire().await?;
                    let order = parse_order_argument(&ctx);
                    let connection = parse_connection_arguments(&ctx)?;

                    let total_count = count_rows(&mut conn, MODEL_TABLE, &None, &None).await?;
                    let (data, page_info) = fetch_multiple_rows(
                        &mut conn,
                        MODEL_TABLE,
                        ID_COLUMN,
                        &None,
                        &order,
                        &None,
                        &connection,
                        total_count,
                    )
                    .await?;
                    let results = connection_output(
                        &data,
                        &MODEL_TYPE_MAPPING,
                        &order,
                        ID_COLUMN,
                        total_count,
                        false,
                        page_info,
                    )?;

                    Ok(Some(Value::Object(results)))
                })
            },
        );

        field = connection_arguments(field);
        field = order_argument(field, MODEL_TYPE_NAME);

        Some(field)
    }

    fn table_name(&self) -> Option<&str> {
        Some(MODEL_TABLE)
    }

