fn handle_cursor(
    cursor: &str,
    order: &Option<Order>,
    direction: CursorDirection,
    id_column: &str,
    is_model: bool,
) -> Result<String> {
    match cursor::decode(cursor) {
        Ok((event_id, field_value)) => match order {
            Some(order) => {
                let field_name = order_column_name(is_model, &order.field);
                Ok(format!(
                    "(({} {} '{}' AND {} = '{}') OR {} {} '{}')",
                    id_column,
                    direction.as_ref(),
                    event_id,
                    field_name,
                    field_value,
                    field_name,
                    direction.as_ref(),
                    field_value
                ))
            }
            None => Ok(format!("{} {} '{}'", id_column, direction.as_ref(), event_id)),
        },
        Err(_) => Err(sqlx::Error::Decode("Invalid cursor format".into())),
    }
}

fn order_column_name(is_model: bool, field: &str) -> String {
    if is_model {
        field.to_string()
    } else {
        format!("external_{}", field)
    }
}

