#[cfg(test)]
mod tests {
    use anyhow::Result;
    use async_graphql::dynamic::Schema;
    use serde_json::Value;

    use crate::schema::build_schema;
    use crate::tests::{run_graphql_query, spinup_types_test, Connection, WorldModel};

    async fn models_query(schema: &Schema, arg: &str) -> Value {
        let query = format!(
            r#"
          {{
             models {} {{
              total_count
              edges {{
                cursor
                node {{
                    id
                    name
                    class_hash
                    transaction_hash
                    created_at
                }}
              }}
              page_info {{
                has_previous_page
                has_next_page
                start_cursor
                end_cursor
              }}
            }}
          }}
        "#,
            arg,
        );

        let result = run_graphql_query(schema, &query).await;
        result.get("models").ok_or("models not found").unwrap().clone()
    }

    // End to end test spins up a test sequencer and deploys types-test project, this takes a while
    // to run so combine all related tests into one
    #[tokio::test(flavor = "multi_thread")]
    async fn models_ordering_test() -> Result<()> {
        let pool = spinup_types_test().await?;
        let schema = build_schema(&pool).await.unwrap();

        // default ordering is stable and returns models by id descending
        let models = models_query(&schema, "").await;
        let connection: Connection<WorldModel> = serde_json::from_value(models).unwrap();
        let default_names: Vec<String> =
            connection.edges.iter().map(|edge| edge.node.name.clone()).collect();

        assert_eq!(connection.total_count, 3);
        assert_eq!(default_names, vec!["Subrecord", "RecordSibling", "Record"]);
        assert!(!connection.page_info.has_previous_page);
        assert!(!connection.page_info.has_next_page);

        // default ordering is stable across queries
        let models = models_query(&schema, "").await;
        let connection: Connection<WorldModel> = serde_json::from_value(models).unwrap();
        let names: Vec<String> = connection.edges.iter().map(|edge| edge.node.name.clone()).collect();
        assert_eq!(names, default_names);

        // order by name ascending
        let models = models_query(&schema, "(order: { field: NAME, direction: ASC })").await;
        let connection: Connection<WorldModel> = serde_json::from_value(models).unwrap();
        let names: Vec<String> = connection.edges.iter().map(|edge| edge.node.name.clone()).collect();

        assert_eq!(connection.total_count, 3);
        assert_eq!(names, vec!["Record", "RecordSibling", "Subrecord"]);
        assert!(!connection.page_info.has_previous_page);
        assert!(!connection.page_info.has_next_page);

        Ok(())
    }
}

