use clap::{Args, Parser};
use url::Url;

#[derive(Debug, Args)]
struct StarknetOptions {
    #[arg(long, env = "STARKNET_RPC_URL")]
    pub rpc_url: Option<Url>,
}

#[derive(Parser)]
struct Command {
    #[clap(flatten)]
    options: StarknetOptions,
}

fn main() {
    // case 1: env only
    std::env::set_var("STARKNET_RPC_URL", "http://localhost:7474/");
    let c = Command::parse_from(["prog"]);
    assert_eq!(c.options.rpc_url.as_ref().unwrap().as_str(), "http://localhost:7474/");
    // case 2: CLI overrides env
    let c = Command::parse_from(["prog", "--rpc-url", "http://localhost:8080"]);
    assert_eq!(c.options.rpc_url.as_ref().unwrap().as_str(), "http://localhost:8080/");
    std::env::remove_var("STARKNET_RPC_URL");
    // case 3: neither
    let c = Command::parse_from(["prog"]);
    assert!(c.options.rpc_url.is_none());
    println!("OK");
}
EOF
