use rand::rngs::SmallRng;
use rand::{RngCore, SeedableRng};
use starknet::core::types::FieldElement;
use starknet::core::utils::get_contract_address;
use starknet::signers::SigningKey;

fn main() {
    let mut seed = [0u8; 32];
    let private_key_bytes: [u8; 32] = {
        let mut rng = SmallRng::from_seed(seed);
        let mut bytes = [0u8; 32];
        rng.fill_bytes(&mut bytes);
        bytes
    };
    let private_key = FieldElement::from_bytes_be(&private_key_bytes).unwrap();
    println!("private_key: {:#x}", private_key);

    let public_key = SigningKey::from_secret_scalar(private_key).verifying_key().scalar();
    println!("public_key:  {:#x}", public_key);

    let old_compiled_hash =
        FieldElement::from_hex_be("0x04d07e40e93398ed3c76981e72dd1fd22557a78ce36c0515f679e27f0bb5bc5f").unwrap();
    let new_class_hash =
        FieldElement::from_hex_be("0x05400e90f7e0ae78bd02c77cd75527280470e2fe19c54970dd79dc37a9d3645c").unwrap();

    for (label, class_hash) in [
        ("with_0x04d07e40...", old_compiled_hash),
        ("with_0x05400e90...", new_class_hash),
    ] {
        let address = get_contract_address(
            FieldElement::from(666u32),
            class_hash,
            &[public_key],
            FieldElement::ZERO,
        );
        println!("addr {label}: {:#x}", address);
    }
}

