use rand::rngs::SmallRng;
use rand::{RngCore, SeedableRng};
use starknet::core::types::FieldElement;
use starknet::core::utils::get_contract_address;
use starknet::signers::SigningKey;

fn derive(seed: [u8; 32]) -> (FieldElement, FieldElement) {
    let mut rng = SmallRng::from_seed(seed);
    let mut private_key_bytes = [0u8; 32];
    rng.fill_bytes(&mut private_key_bytes);
    private_key_bytes[0] %= 0x8;

    let private_key =
        FieldElement::from_bytes_be(&private_key_bytes).expect("able to create FieldElement");
    let public_key = SigningKey::from_secret_scalar(private_key).verifying_key().scalar();
    (private_key, public_key)
}

#[test]
fn verify_account_derivation() {
    // seed "0" -> parse_seed(bytes of "0" = [0x30], padded)
    let mut seed_str = [0u8; 32];
    seed_str[0] = b'0';
    let (priv_0x30, pub_0x30) = derive(seed_str);
    println!("seed\"0\" (0x30 first byte)");
    println!("  private_key: {:#x}", priv_0x30);
    println!("  public_key:  {:#x}", pub_0x30);

    let old_hash =
        FieldElement::from_hex_be("0x04d07e40e93398ed3c76981e72dd1fd22557a78ce36c0515f679e27f0bb5bc5f")
            .unwrap();
    let new_hash =
        FieldElement::from_hex_be("0x05400e90f7e0ae78bd02c77cd75527280470e2fe19c54970dd79dc37a9d3645c")
            .unwrap();

    for (label, class_hash) in [
        ("with_0x04d07e40e9...", old_hash),
        ("with_0x05400e90f7...", new_hash),
    ] {
        let address = get_contract_address(
            FieldElement::from(666u32),
            class_hash,
            &[pub_0x30],
            FieldElement::ZERO,
        );
        println!("addr {label}: {:#x}", address);
    }

    let expected_priv_key = FieldElement::from_hex_be(
        "0x1800000000300000180000000000030000000000003006001800006600",
    )
    .unwrap();
    println!("expected priv key: {:#x}", expected_priv_key);
}

